mapper.select:
SELECT bno, title, writer, regdate, updatedate, replycnt
FROM (
    SELECT ROW_NUMBER() OVER (ORDER BY bno DESC) rn,
           bno, title, writer, regdate, updatedate, replycnt
    FROM tbl_board
    WHERE  bno > 0
)
WHERE rn > (CAST(#{pageNum} AS DECIMAL(19,0)) - 1) * #{amount}
  AND rn <= CAST(#{pageNum} AS DECIMAL(19,0)) * #{amount}
ORDER BY rn
